  4	pub(crate) struct Reader<'a> { pub bytes: &'a [u8], pub base: usize, pub index: usize }
  5	
  6	impl<'a> Reader<'a> {
  7	    pub(crate) fn absolute(&self) -> usize { self.base + self.index }
  8	    pub(crate) fn skip_space(&mut self) {
  9	        while matches!(self.bytes.get(self.index), Some(b' ' | b'\t' | b'\r' | b'\n')) { self.index += 1; }
 10	    }
 11	    pub(crate) fn skip_separators(&mut self) {
 12	        while matches!(self.bytes.get(self.index), Some(b' ' | b'\t' | b'\r' | b'\n' | b',')) { self.index += 1; }
 13	    }
 14	    pub(crate) fn number(&mut self) -> Result<(f64, Span), Diagnostic> {
 15	        self.skip_space();
 16	        let start = self.index;
 17	        let negative = match self.bytes.get(self.index) {
 18	            Some(b'-') => { self.index += 1; true },
 19	            Some(b'+') => { self.index += 1; false },
 20	            _ => false,
 21	        };
 22	        let mut value = 0.0;
 23	        let mut digits = 0usize;
 24	        while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
 25	            value = value * 10.0 + f64::from(byte - b'0');
 26	            self.index += 1;
 27	            digits += 1;
 28	            if !value.is_finite() || value > 1.0e300 { return Err(self.number_error()); }
 29	        }
 30	        if self.bytes.get(self.index) == Some(&b'.') {
 31	            self.index += 1;
 32	            let mut scale = 0.1;
 33	            while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
 34	                value += f64::from(byte - b'0') * scale;
 35	                scale *= 0.1;
 36	                self.index += 1;
 37	                digits += 1;
 38	            }
 39	        }
 40	        if digits == 0 { self.index = start; return Err(self.number_error()); }
 41	        if matches!(self.bytes.get(self.index), Some(b'e' | b'E')) {
 42	            let mut lookahead = self.index + 1;
 43	            if matches!(self.bytes.get(lookahead), Some(b'+' | b'-')) { lookahead += 1; }
 44	            if matches!(self.bytes.get(lookahead), Some(b'0'..=b'9')) {
 45	                self.index += 1;
 46	                let exponent_negative = match self.bytes.get(self.index) {
 47	                    Some(b'-') => { self.index += 1; true },
 48	                    Some(b'+') => { self.index += 1; false },
 49	                    _ => false,
 50	                };
 51	                let mut exponent = 0i32;
 52	                while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
 53	                    if exponent < 10_000 { exponent = exponent.saturating_mul(10).saturating_add(i32::from(byte - b'0')); }
 54	                    self.index += 1;
 55	                }
 56	                if exponent_negative { exponent = -exponent; }
 57	                value *= 10.0_f64.powi(exponent);
 58	            }
 59	        }
 60	        if negative { value = -value; }
 61	        if !value.is_finite() || value.abs() > 1.0e6 { return Err(self.number_error()); }
 62	        Ok((value, Span { start: self.base + start, end: self.absolute() }))
 63	    }
 64	    pub(crate) fn arc_flag(&mut self) -> Result<(f64, Span), Diagnostic> {
 65	        self.skip_space();
 66	        let start = self.index;
 67	        match self.bytes.get(self.index) {
 68	            Some(b'0' | b'1') => {
 69	                let value = f64::from(self.bytes[self.index] - b'0');
 70	                self.index += 1;
 71	                Ok((value, Span { start: self.base + start, end: self.absolute() }))
 72	            }
 73	            _ => Err(self.number_error()),
 74	        }
 75	    }
 76	    fn number_error(&self) -> Diagnostic { Diagnostic { kind: DiagnosticKind::Path, offset: self.absolute() } }
 77	}
