 79	pub(crate) fn operand_boundary(reader: &mut Reader<'_>, previous_number: bool, previous_arc_flag: bool, command: u8, argument: usize) -> bool {
 80	    let before = reader.index;
 81	    reader.skip_separators();
 82	    if !previous_number || reader.index != before { return true; }
 83	    if matches!(reader.bytes.get(reader.index), Some(b'+' | b'-' | b'.')) { return true; }
 84	    command == b'A' && (argument == 4 || (argument == 5 && previous_arc_flag))
 85	}
 86	
 87	pub(crate) fn validate_commas(bytes: &[u8], span: Span) -> Result<(), Diagnostic> {
 88	    for (index, byte) in bytes.iter().enumerate() {
 89	        if *byte != b',' { continue; }
 90	        let mut left = index;
 91	        let mut right = index + 1;
 92	        while left > 0 && is_space(bytes[left - 1]) { left -= 1; }
 93	        while right < bytes.len() && is_space(bytes[right]) { right += 1; }
 94	        let left_ok = left > 0 && (bytes[left - 1].is_ascii_digit() || bytes[left - 1] == b'.');
 95	        let right_ok = right < bytes.len() && (bytes[right].is_ascii_digit() || matches!(bytes[right], b'.' | b'+' | b'-'));
 96	        if !left_ok || !right_ok || bytes.get(left.wrapping_sub(1)) == Some(&b',') || bytes.get(right) == Some(&b',') {
 97	            return Err(Diagnostic { kind: DiagnosticKind::Path, offset: span.start + index });
 98	        }
 99	    }
100	    Ok(())
101	}
102	
103	fn is_space(byte: u8) -> bool { matches!(byte, b' ' | b'\t' | b'\r' | b'\n') }
