  7	pub(crate) fn parse(source: &[u8], span: Span, transform: Affine, options: ParseOptions) -> Result<PathDocument, Diagnostic> {
  8	    let bytes = span.slice(source).ok_or_else(|| failure(DiagnosticKind::InvalidSpan, span.start))?;
  9	    if !affine_valid(transform) { return Err(failure(DiagnosticKind::InvalidTransform, span.start)); }
 10	    validate_commas(bytes, span)?;
 11	    Parser {
 12	        reader: Reader { bytes, base: span.start, index: 0 },
 13	        transform,
 14	        flatness: flatten::tolerance(transform),
 15	        max_commands: options.max_commands.min(MAX_PATH_COMMANDS),
 16	        max_edges: options.max_edges.min(MAX_PATH_EDGES),
 17	        max_numbers: options.max_numbers.min(MAX_PATH_NUMBERS),
 18	        command_count: 0,
 19	        document: PathDocument::new(),
 20	    }.run()
 21	}
 22	
 23	struct Parser<'a> {
 24	    reader: Reader<'a>,
 25	    transform: Affine,
 26	    flatness: f64,
 27	    max_commands: usize,
 28	    max_edges: usize,
 29	    max_numbers: usize,
 30	    command_count: usize,
 31	    document: PathDocument,
 32	}
 33	
 34	impl Parser<'_> {
 35	    fn run(mut self) -> Result<PathDocument, Diagnostic> {
 36	        let (mut current, mut first, mut cubic_control, mut quad_control) = (Point { x: 0.0, y: 0.0 }, Point { x: 0.0, y: 0.0 }, Point { x: 0.0, y: 0.0 }, Point { x: 0.0, y: 0.0 });
 37	        let (mut command, mut open, mut path_first) = (0u8, false, true);
 38	        let (mut cubic_reflect, mut quad_reflect) = (false, false);
 39	        let (mut previous_number, mut previous_arc_flag) = (false, false);
 40	        let mut current_subpath_edge = 0;
 41	        let mut last_group_offset = self.reader.base;
 42	
 43	        while self.reader.index < self.reader.bytes.len() {
 44	            let gap_start = self.reader.index;
 45	            self.reader.skip_separators();
 46	            let had_separator = self.reader.index != gap_start;
 47	            if self.reader.index >= self.reader.bytes.len() { break; }
 48	            let segment_start = self.reader.index;
 49	            let mut command_offset = None;
 50	            if self.reader.bytes[self.reader.index].is_ascii_alphabetic() {
 51	                command_offset = Some(self.reader.absolute());
 52	                command = self.reader.bytes[self.reader.index];
 53	                self.reader.index += 1;
 54	                previous_number = false;
 55	            } else if command == 0 || command == b'Z' || command == b'z' {
 56	                return Err(failure(DiagnosticKind::Path, self.reader.absolute()));
 57	            } else {
 58	                if previous_number && !had_separator && !matches!(self.reader.bytes[self.reader.index], b'+' | b'-') {
 59	                    return Err(failure(DiagnosticKind::Path, self.reader.absolute()));
 60	                }
 61	                previous_number = false;
 62	            }
 63	            self.command_count = self.command_count.checked_add(1).ok_or_else(|| failure(DiagnosticKind::Limit, self.reader.absolute()))?;
 64	            if self.command_count > self.max_commands { return Err(failure(DiagnosticKind::Limit, self.reader.absolute())); }
 65	            let segment_command = command;
 66	            let relative = command.is_ascii_lowercase();
 67	            let upper = command.to_ascii_uppercase();
 68	            if path_first && upper != b'M' { return Err(failure(DiagnosticKind::Path, self.reader.absolute().saturating_sub(1))); }
 69	            path_first = false;
 70	
 71	            if upper == b'Z' {
 72	                let first_edge = self.document.edges.len();
 73	                if open {
 74	                    self.add_edge(current, first, last_group_offset)?;
 75	                    self.record_subpath(current_subpath_edge, true, last_group_offset)?;
 76	                }
 77	                let segment_index = self.record_segment(segment_command, segment_start, self.reader.index, command_offset, &[], first_edge)?;
 78	                self.document.segments[segment_index].edge_count = self.document.edges.len() - first_edge;
 79	                current = first;
 80	                open = false;
 81	                command = 0;
 82	                cubic_reflect = false;
 83	                quad_reflect = false;
 84	                continue;
 85	            }
 86	            if !matches!(upper, b'M' | b'L' | b'H' | b'V' | b'C' | b'S' | b'Q' | b'T' | b'A') {
 87	                return Err(failure(DiagnosticKind::Unsupported, self.reader.absolute().saturating_sub(1)));
 88	            }
 89	            let count = match upper { b'H' | b'V' => 1, b'C' => 6, b'S' | b'Q' => 4, b'T' => 2, b'A' => 7, _ => 2 };
 90	            let group_start = self.reader.index;
 91	            last_group_offset = self.reader.base + group_start;
 92	            let mut values = [0.0; 7];
 93	            let mut source_numbers = [PathNumber { source: Span { start: 0, end: 0 }, value: 0.0 }; 7];
 94	            for index in 0..count {
 95	                if !operand_boundary(&mut self.reader, previous_number, previous_arc_flag, upper, index) {
 96	                    return Err(failure(DiagnosticKind::Path, self.reader.absolute()));
 97	                }
 98	                let parsed = if upper == b'A' && (index == 3 || index == 4) { self.reader.arc_flag() } else { self.reader.number() };
 99	                let (value, source_span) = parsed.map_err(|_| failure(DiagnosticKind::Path, self.reader.base + group_start))?;
100	                values[index] = value;
101	                source_numbers[index] = PathNumber { source: source_span, value };
102	                previous_number = true;
103	                previous_arc_flag = upper == b'A' && (index == 3 || index == 4);
104	            }
105	            let first_edge = self.document.edges.len();
106	            let segment_index = self.record_segment(segment_command, segment_start, self.reader.index, command_offset, &source_numbers[..count], first_edge)?;
107	            let mut point = current;
108	            let mut drawn = false;
109	            match upper {
110	                b'H' => point.x = if relative { current.x + values[0] } else { values[0] },
111	                b'V' => point.y = if relative { current.y + values[0] } else { values[0] },
112	                b'C' => {
113	                    let mut c1 = Point { x: values[0], y: values[1] };
114	                    let mut c2 = Point { x: values[2], y: values[3] };
115	                    point = Point { x: values[4], y: values[5] };
116	                    if relative { c1 = add(c1, current); c2 = add(c2, current); point = add(point, current); }
117	                    self.check_points(&[c1, c2, point], group_start)?;
118	                    self.add_curve([current, c1, c2, point], self.reader.base + group_start)?;
119	                    cubic_control = c2;
120	                    cubic_reflect = true;
121	                    quad_reflect = false;
122	                    drawn = true;
123	                }
124	                b'S' => {
125	                    let c1 = if cubic_reflect { reflect(current, cubic_control) } else { current };
126	                    let mut c2 = Point { x: values[0], y: values[1] };
127	                    point = Point { x: values[2], y: values[3] };
128	                    if relative { c2 = add(c2, current); point = add(point, current); }
129	                    self.check_points(&[c1, c2, point], group_start)?;
130	                    self.add_curve([current, c1, c2, point], self.reader.base + group_start)?;
131	                    cubic_control = c2;
132	                    cubic_reflect = true;
133	                    quad_reflect = false;
134	                    drawn = true;
135	                }
136	                b'Q' => {
137	                    let mut control = Point { x: values[0], y: values[1] };
138	                    point = Point { x: values[2], y: values[3] };
139	                    if relative { control = add(control, current); point = add(point, current); }
140	                    self.check_points(&[control, point], group_start)?;
141	                    self.add_quad(current, control, point, self.reader.base + group_start)?;
142	                    quad_control = control;
143	                    quad_reflect = true;
144	                    cubic_reflect = false;
145	                    drawn = true;
146	                }
147	                b'T' => {
148	                    let control = if quad_reflect { reflect(current, quad_control) } else { current };
149	                    point = Point { x: values[0], y: values[1] };
150	                    if relative { point = add(point, current); }
151	                    self.check_points(&[control, point], group_start)?;
152	                    self.add_quad(current, control, point, self.reader.base + group_start)?;
153	                    quad_control = control;
154	                    quad_reflect = true;
155	                    cubic_reflect = false;
156	                    drawn = true;
157	                }
158	                b'A' => {
159	                    if (values[3] != 0.0 && values[3] != 1.0) || (values[4] != 0.0 && values[4] != 1.0) || values[0] < 0.0 || values[1] < 0.0 {
160	                        return Err(failure(DiagnosticKind::Path, self.reader.base + group_start));
161	                    }
162	                    point = Point { x: values[5], y: values[6] };
163	                    if relative { point = add(point, current); }
164	                    self.check_points(&[point], group_start)?;
165	                    flatten::arc(&mut self.document.edges, self.transform, current, values[0], values[1], values[2], values[3] == 1.0, values[4] == 1.0, point, self.flatness, self.max_edges, self.reader.base + group_start)?;
166	                    cubic_reflect = false;
167	                    quad_reflect = false;
168	                    drawn = true;
169	                }
170	                _ => {
171	                    point = Point { x: values[0], y: values[1] };
172	                    if relative { point = add(point, current); }
173	                    if upper == b'M' {
174	                        self.check_points(&[point], group_start)?;
175	                        if open {
176	                            self.add_edge(current, first, self.reader.base + group_start)?;
177	                            self.record_subpath(current_subpath_edge, false, self.reader.base + group_start)?;
178	                        }
179	                        current = point;
180	                        first = point;
181	                        current_subpath_edge = self.document.edges.len();
182	                        open = true;
183	                        command = if relative { b'l' } else { b'L' };
184	                        cubic_reflect = false;
185	                        quad_reflect = false;
186	                        continue;
187	                    }
188	                }
189	            }
190	            if matches!(upper, b'M' | b'L' | b'H' | b'V') { cubic_reflect = false; quad_reflect = false; }
191	            self.check_points(&[point], group_start)?;
192	            if !drawn { self.add_edge(current, point, self.reader.base + group_start)?; }
193	            self.document.segments[segment_index].edge_count = self.document.edges.len() - first_edge;
194	            current = point;
195	            open = true;
196	        }
197	        if open {
198	            self.add_edge(current, first, last_group_offset)?;
199	            self.record_subpath(current_subpath_edge, false, last_group_offset)?;
200	        }
201	        Ok(self.document)
202	    }
203	
204	    fn check_points(&self, points: &[Point], group_start: usize) -> Result<(), Diagnostic> {
205	        if points.iter().all(|point| flatten::bounded(*point)) { Ok(()) } else { Err(failure(DiagnosticKind::Number, self.reader.base + group_start)) }
206	    }
207	    fn add_edge(&mut self, from: Point, to: Point, offset: usize) -> Result<(), Diagnostic> {
208	        flatten::edge(&mut self.document.edges, self.transform, from, to, self.max_edges, offset)
209	    }
210	    fn add_curve(&mut self, points: [Point; 4], offset: usize) -> Result<(), Diagnostic> {
211	        flatten::curve(&mut self.document.edges, self.transform, points, self.flatness, self.max_edges, offset)
212	    }
213	    fn add_quad(&mut self, from: Point, control: Point, to: Point, offset: usize) -> Result<(), Diagnostic> {
214	        let c1 = Point { x: from.x + (control.x - from.x) * (2.0 / 3.0), y: from.y + (control.y - from.y) * (2.0 / 3.0) };
215	        let c2 = Point { x: to.x + (control.x - to.x) * (2.0 / 3.0), y: to.y + (control.y - to.y) * (2.0 / 3.0) };
216	        self.add_curve([from, c1, c2, to], offset)
217	    }
218	    fn record_subpath(&mut self, first_edge: usize, closed: bool, offset: usize) -> Result<(), Diagnostic> {
219	        let edge_count = self.document.edges.len() - first_edge;
220	        if edge_count == 0 { return Ok(()); }
221	        if self.document.subpaths.len() >= MAX_PATH_EDGES { return Err(failure(DiagnosticKind::Limit, offset)); }
222	        self.document.subpaths.try_reserve(1).map_err(|_| oom(offset))?;
223	        self.document.subpaths.push(PathSubpath { first_edge, edge_count, closed });
224	        Ok(())
225	    }
226	    fn record_segment(&mut self, command: u8, start: usize, end: usize, command_offset: Option<usize>, numbers: &[PathNumber], first_edge: usize) -> Result<usize, Diagnostic> {
227	        let offset = self.reader.base + start;
228	        if self.document.segments.len() >= self.max_commands || numbers.len() > self.max_numbers.saturating_sub(self.document.numbers.len()) {
229	            return Err(failure(DiagnosticKind::Limit, offset));
230	        }
231	        self.document.segments.try_reserve(1).map_err(|_| oom(offset))?;
232	        self.document.numbers.try_reserve(numbers.len()).map_err(|_| oom(offset))?;
233	        let first_number = self.document.numbers.len();
234	        self.document.numbers.extend_from_slice(numbers);
235	        let index = self.document.segments.len();
236	        self.document.segments.push(PathSegment {
237	            command,
238	            source: Span { start: offset, end: self.reader.base + end },
239	            command_offset,
240	            first_number,
241	            number_count: numbers.len(),
242	            first_edge,
243	            edge_count: 0,
244	        });
245	        Ok(index)
246	    }
247	}
