249	fn add(a: Point, b: Point) -> Point { Point { x: a.x + b.x, y: a.y + b.y } }
250	fn reflect(origin: Point, control: Point) -> Point { Point { x: 2.0 * origin.x - control.x, y: 2.0 * origin.y - control.y } }
