  6	/* Per-path command budget; a single CAD path routinely carries hundreds of
  7	 * thousands of segments. */
  8	#define SHAPE_MAX_COMMANDS (4U * 1024U * 1024U)
  9	#define SHAPE_MAX_COORD 1000000.0
 10	typedef svg_shape_builder builder;
 11	typedef svg_shape_number_reader number_reader;
 12	
 13	static bool record_path_subpath(builder *b, size_t first_edge, bool closed)
 14	{
 15	    size_t count = b->doc->edge_count - first_edge;
 16	    if (count == 0U) return true;
 17	    if (b->doc->path_subpath_count >= SVG_SHAPE_MAX_EDGES ||
 18	        b->doc->path_subpath_count >= SIZE_MAX / sizeof(*b->doc->path_subpaths)) {
 19	        svg_shape_fail(b->diag, SVG_SHAPE_ERROR_LIMIT, b->offset);
 20	        return false;
 21	    }
 22	    if (b->doc->path_subpath_count == b->subpath_capacity) {
 23	        size_t next = b->subpath_capacity == 0U ? 16U : b->subpath_capacity * 2U;
 24	        if (next < b->subpath_capacity || next > SVG_SHAPE_MAX_EDGES)
 25	            next = SVG_SHAPE_MAX_EDGES;
 26	        if (next > SIZE_MAX / sizeof(*b->doc->path_subpaths)) {
 27	            svg_shape_fail(b->diag, SVG_SHAPE_ERROR_LIMIT, b->offset);
 28	            return false;
 29	        }
 30	        svg_shape_path_subpath *grown = svg_shape_realloc(
 31	            b->doc->path_subpaths, next * sizeof(*grown));
 32	        if (grown == NULL) {
 33	            svg_shape_fail(b->diag, SVG_SHAPE_ERROR_OOM, b->offset);
 34	            return false;
 35	        }
 36	        b->doc->path_subpaths = grown;
 37	        b->subpath_capacity = next;
 38	    }
 39	    b->doc->path_subpaths[b->doc->path_subpath_count++] =
 40	        (svg_shape_path_subpath){first_edge, count, closed};
