 43	static bool add_arc(builder *b, geom_point from, double rx, double ry, double rotation,
 44	                    bool large, bool sweep, geom_point to, size_t offset)
 45	{
 46	    rx = fabs(rx); ry = fabs(ry);
 47	    if (rx == 0.0 || ry == 0.0) return svg_shape_builder_add_edge(b, from, to);
 48	    if (from.x == to.x && from.y == to.y) return true;
 49	    double phi = rotation * 0.017453292519943295;
 50	    double cp = cos(phi), sp = sin(phi);
 51	    double dx = (from.x - to.x) * 0.5, dy = (from.y - to.y) * 0.5;
 52	    double xp = cp * dx + sp * dy, yp = -sp * dx + cp * dy;
 53	    double scale = xp*xp/(rx*rx) + yp*yp/(ry*ry);
 54	    if (!isfinite(scale)) { svg_shape_fail(b->diag, SVG_SHAPE_ERROR_NUMBER, offset); return false; }
 55	    if (scale > 1.0) { double factor=sqrt(scale); rx*=factor; ry*=factor; }
 56	    double numerator=rx*rx*ry*ry-rx*rx*yp*yp-ry*ry*xp*xp;
 57	    double denominator=rx*rx*yp*yp+ry*ry*xp*xp;
 58	    double ratio=denominator==0.0?0.0:fmax(0.0,numerator/denominator);
 59	    double sign=large==sweep?-1.0:1.0;
 60	    double coef=sign*sqrt(ratio);
 61	    double cxp=coef*(rx*yp/ry), cyp=coef*(-ry*xp/rx);
 62	    double cx=cp*cxp-sp*cyp+(from.x+to.x)*0.5;
 63	    double cy=sp*cxp+cp*cyp+(from.y+to.y)*0.5;
 64	    double ux=(xp-cxp)/rx, uy=(yp-cyp)/ry;
 65	    double vx=(-xp-cxp)/rx, vy=(-yp-cyp)/ry;
 66	    double start=atan2(uy,ux), delta=atan2(ux*vy-uy*vx,ux*vx+uy*vy);
 67	    if (!sweep && delta>0.0) delta-=6.283185307179586;
 68	    if (sweep && delta<0.0) delta+=6.283185307179586;
 69	    double radius=fmax(rx,ry);
 70	    double tolerance=svg_shape_transformed_flatness_tolerance(b);
 71	    double max_angle=radius<=tolerance?6.283185307179586:2.0*acos(fmax(-1.0,1.0-tolerance/radius));
 72	    double raw=ceil(fabs(delta)/max_angle);
 73	    if (!isfinite(raw) || raw>(double)SVG_SHAPE_MAX_EDGES) { svg_shape_fail(b->diag,SVG_SHAPE_ERROR_LIMIT,offset); return false; }
 74	    unsigned steps=(unsigned)raw; if(steps==0U)steps=1U;
 75	    geom_point previous=from;
 76	    for(unsigned i=1U;i<=steps;i++){
 77	        double angle=start+delta*(double)i/(double)steps;
 78	        geom_point point={cx+cp*rx*cos(angle)-sp*ry*sin(angle),cy+sp*rx*cos(angle)+cp*ry*sin(angle)};
 79	        if(i==steps)point=to;
 80	        if(!geom_finite_point(point)||fabs(point.x)>SHAPE_MAX_COORD||fabs(point.y)>SHAPE_MAX_COORD){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,offset);return false;}
 81	        if(!svg_shape_builder_add_edge(b,previous,point))return false; previous=point;
 82	    }
 83	    return true;
 84	}
