 86	static bool record_path_segment(builder *builder, char command,
 87	                                size_t source_offset, size_t source_length,
 88	                                size_t command_offset,
 89	                                const svg_shape_path_number *numbers,
 90	                                size_t number_count)
 91	{
 92	    svg_shape_document *document = builder->doc;
 93	    if (document->path_segment_count >= SVG_SHAPE_MAX_COMMANDS ||
 94	        number_count > SVG_SHAPE_MAX_PATH_NUMBERS -
 95	                       document->path_number_count) {
 96	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, source_offset);
 97	        return false;
 98	    }
 99	    if (document->path_segment_count == builder->path_segment_capacity) {
100	        size_t next = builder->path_segment_capacity == 0U ? 32U :
101	                      builder->path_segment_capacity * 2U;
102	        if (next < builder->path_segment_capacity ||
103	            next > SVG_SHAPE_MAX_COMMANDS) next = SVG_SHAPE_MAX_COMMANDS;
104	        if (next > SIZE_MAX / sizeof(*document->path_segments)) {
105	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, source_offset);
106	            return false;
107	        }
108	        svg_shape_path_segment *grown = svg_shape_realloc(
109	            document->path_segments, next * sizeof(*grown));
110	        if (grown == NULL) {
111	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_OOM, source_offset);
112	            return false;
113	        }
114	        document->path_segments = grown;
115	        builder->path_segment_capacity = next;
116	    }
117	    size_t required_numbers = document->path_number_count + number_count;
118	    if (required_numbers > builder->path_number_capacity) {
119	        size_t next = builder->path_number_capacity == 0U ? 64U :
120	                      builder->path_number_capacity;
121	        while (next < required_numbers) {
122	            if (next > SVG_SHAPE_MAX_PATH_NUMBERS / 2U) {
123	                next = SVG_SHAPE_MAX_PATH_NUMBERS;
124	                break;
125	            }
126	            next *= 2U;
127	        }
128	        if (next > SIZE_MAX / sizeof(*document->path_numbers)) {
129	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, source_offset);
130	            return false;
131	        }
132	        svg_shape_path_number *grown = svg_shape_realloc(
133	            document->path_numbers, next * sizeof(*grown));
134	        if (grown == NULL) {
135	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_OOM, source_offset);
136	            return false;
137	        }
138	        document->path_numbers = grown;
139	        builder->path_number_capacity = next;
140	    }
141	    size_t first_number = document->path_number_count;
142	    if (number_count != 0U) {
143	        memcpy(document->path_numbers + first_number, numbers,
144	               number_count * sizeof(*numbers));
145	        document->path_number_count += number_count;
146	    }
147	    document->path_segments[document->path_segment_count++] =
148	        (svg_shape_path_segment){
149	            .command = command,
150	            .source_offset = source_offset,
151	            .source_length = source_length,
152	            .command_offset = command_offset,
153	            .first_number = first_number,
154	            .number_count = number_count,
155	            .first_edge = document->edge_count,
156	            .edge_count = 0U,
157	            .shape_index = builder->shape_index};
158	    return true;
159	}
