161	static bool add_path_quad(builder *b, geom_point p0, geom_point control,
162	                          geom_point p2)
163	{
164	    geom_point c1 = {p0.x + (control.x - p0.x) * (2.0 / 3.0),
165	                     p0.y + (control.y - p0.y) * (2.0 / 3.0)};
166	    geom_point c2 = {p2.x + (control.x - p2.x) * (2.0 / 3.0),
167	                     p2.y + (control.y - p2.y) * (2.0 / 3.0)};
168	    return svg_shape_builder_add_curve(b, p0, c1, c2, p2);
169	}
