171	bool svg_shape_path_decode(builder *b, base_bytes src, svg_xml_span span)
172	{
173	    size_t shape_subpath_start = b->doc->path_subpath_count;
174	    size_t current_subpath_edge = b->doc->edge_count;
175	    number_reader r={src.ptr+span.offset,span.length,0,span.offset};
176	    for(size_t i=0;i<span.length;i++)if(r.p[i]==','){
177	        size_t left=i,right=i+1U;
178	        while(left>0U&&(r.p[left-1U]==' '||r.p[left-1U]=='\t'||r.p[left-1U]=='\r'||r.p[left-1U]=='\n'))left--;
179	        while(right<span.length&&(r.p[right]==' '||r.p[right]=='\t'||r.p[right]=='\r'||r.p[right]=='\n'))right++;
180	        if(left==0U||right==span.length||r.p[left-1U]==','||r.p[right]==','||
181	           !((r.p[left-1U]>='0'&&r.p[left-1U]<='9')||r.p[left-1U]=='.')||
182	           !((r.p[right]>='0'&&r.p[right]<='9')||r.p[right]=='.'||r.p[right]=='+'||r.p[right]=='-')){
183	            svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+i);return false;
184	        }
185	    }
186	    geom_point current={0,0}, first={0,0}, cubic_control={0,0}, quad_control={0,0};
187	    char cmd=0; bool open=false, path_first=true;
188	    bool cubic_reflect=false, quad_reflect=false;
189	    bool previous_number=false, previous_arc_flag=false;
190	    while (r.i < r.n) {
191	        size_t gap_start=r.i;svg_shape_skip_path_separators(&r);bool had_separator=r.i!=gap_start;if(r.i>=r.n)break;
192	        size_t segment_start = r.i;
193	        size_t command_offset = SIZE_MAX;
194	        if ((r.p[r.i] >= 'A'&&r.p[r.i]<='Z')||(r.p[r.i]>='a'&&r.p[r.i]<='z')) {command_offset=span.offset+r.i;cmd=(char)r.p[r.i++];previous_number=false;previous_arc_flag=false;}
195	        else if(cmd==0 || cmd=='Z' || cmd=='z') { svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+r.i); return false; }
196	        else {
197	            if(previous_number&&!had_separator&&!(r.p[r.i]=='+'||r.p[r.i]=='-')) {svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+r.i);return false;}
198	            previous_number=false;previous_arc_flag=false;
199	        }
200	        if (++b->command_count > SHAPE_MAX_COMMANDS) { svg_shape_fail(b->diag,SVG_SHAPE_ERROR_LIMIT,span.offset+r.i); return false; }
201	        char segment_command = cmd;
202	        bool rel=cmd>='a'&&cmd<='z'; char upper=rel?(char)(cmd-'a'+'A'):cmd;
203	        if(path_first&&upper!='M'){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+r.i-1U);return false;}
204	        path_first=false;
205	        if(upper=='Z') {
206	            size_t segment_index = b->doc->path_segment_count;
207	            size_t closing_edge = b->doc->edge_count;
208	            if (open && (!svg_shape_builder_add_edge(b,current,first) ||
209	                         !record_path_subpath(b,current_subpath_edge,true)))
210	                return false;
211	            if (!record_path_segment(b, segment_command,
212	                    span.offset + segment_start, r.i - segment_start,
213	                    command_offset, NULL, 0U)) return false;
214	            if (segment_index < b->doc->path_segment_count) {
215	                b->doc->path_segments[segment_index].first_edge = closing_edge;
216	                b->doc->path_segments[segment_index].edge_count =
217	                    b->doc->edge_count - closing_edge;
218	            }
219	            current=first;open=false;cmd=0;cubic_reflect=false;quad_reflect=false;continue;
220	        }
221	        if(upper!='M'&&upper!='L'&&upper!='H'&&upper!='V'&&upper!='C'&&upper!='S'&&upper!='Q'&&upper!='T'&&upper!='A') { svg_shape_fail(b->diag,SVG_SHAPE_ERROR_UNSUPPORTED,span.offset+r.i-1U);return false; }
222	        double v[7]={0}; unsigned count=upper=='H'||upper=='V'?1U:upper=='C'?6U:(upper=='S'||upper=='Q')?4U:upper=='T'?2U:upper=='A'?7U:2U;
223	        size_t group_start=r.i; b->offset=span.offset+group_start;
224	        svg_shape_path_number source_numbers[7] = {{0}};
225	        for(unsigned i=0;i<count;i++){
226	            if(!svg_shape_path_operand_boundary(&r,previous_number,previous_arc_flag,upper,i)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+r.i);return false;}
227	            size_t number_start = r.i;
228	            bool ok=upper=='A'&&(i==3U||i==4U)?svg_shape_read_arc_flag(&r,&v[i]):svg_shape_read_number_value(&r,&v[i]);
229	            if(!ok){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+group_start);return false;}
230	            source_numbers[i] = (svg_shape_path_number){
231	                span.offset + number_start, r.i - number_start, v[i]};
232	            previous_number=true;previous_arc_flag=upper=='A'&&(i==3U||i==4U);
233	        }
234	        size_t segment_index = b->doc->path_segment_count;
235	        size_t segment_first_edge = b->doc->edge_count;
236	        if (!record_path_segment(b, segment_command,
237	                span.offset + segment_start, r.i - segment_start,
238	                command_offset, source_numbers, count)) return false;
239	        geom_point p=current; bool drawn=false;
240	        if(upper=='H')p.x=rel?current.x+v[0]:v[0];
241	        else if(upper=='V')p.y=rel?current.y+v[0]:v[0];
242	        else if(upper=='C'||upper=='S'||upper=='Q'||upper=='T'||upper=='A') {
243	            if(upper=='C') { geom_point c1={v[0],v[1]},c2={v[2],v[3]};p=(geom_point){v[4],v[5]}; if(rel){c1.x+=current.x;c1.y+=current.y;c2.x+=current.x;c2.y+=current.y;p.x+=current.x;p.y+=current.y;} if(!svg_shape_point_bounded(c1)||!svg_shape_point_bounded(c2)||!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;} if(!svg_shape_builder_add_curve(b,current,c1,c2,p))return false;drawn=true; }
244	            else if(upper=='S') { geom_point c1=cubic_reflect?(geom_point){2.0*current.x-cubic_control.x,2.0*current.y-cubic_control.y}:current; geom_point c2={v[0],v[1]};p=(geom_point){v[2],v[3]};if(rel){c2.x+=current.x;c2.y+=current.y;p.x+=current.x;p.y+=current.y;}if(!svg_shape_point_bounded(c1)||!svg_shape_point_bounded(c2)||!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;}if(!svg_shape_builder_add_curve(b,current,c1,c2,p))return false;cubic_control=c2;cubic_reflect=true;quad_reflect=false;drawn=true; }
245	            else if(upper=='Q') {geom_point c={v[0],v[1]};p=(geom_point){v[2],v[3]};if(rel){c.x+=current.x;c.y+=current.y;p.x+=current.x;p.y+=current.y;}if(!svg_shape_point_bounded(c)||!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;}if(!add_path_quad(b,current,c,p))return false;quad_control=c;quad_reflect=true;cubic_reflect=false;drawn=true;}
246	            else if(upper=='T') {geom_point c=quad_reflect?(geom_point){2.0*current.x-quad_control.x,2.0*current.y-quad_control.y}:current;p=(geom_point){v[0],v[1]};if(rel){p.x+=current.x;p.y+=current.y;}if(!svg_shape_point_bounded(c)||!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;}if(!add_path_quad(b,current,c,p))return false;quad_control=c;quad_reflect=true;cubic_reflect=false;drawn=true;}
247	            else { if((v[3]!=0.0&&v[3]!=1.0)||(v[4]!=0.0&&v[4]!=1.0)||v[0]<0.0||v[1]<0.0){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_PATH,span.offset+group_start);return false;} p=(geom_point){v[5],v[6]};if(rel){p.x+=current.x;p.y+=current.y;}if(!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;} if(!add_arc(b,current,v[0],v[1],v[2],v[3]==1.0,v[4]==1.0,p,span.offset+group_start))return false;drawn=true; }
248	            if(upper=='C'){cubic_control=(geom_point){v[2],v[3]};if(rel){cubic_control.x+=current.x;cubic_control.y+=current.y;}cubic_reflect=true;quad_reflect=false;}
249	            if(upper=='A'){cubic_reflect=false;quad_reflect=false;}
250	        } else {p=(geom_point){v[0],v[1]};if(rel){p.x+=current.x;p.y+=current.y;} if(upper=='M'){if(!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;}if(open&&(!svg_shape_builder_add_edge(b,current,first)||!record_path_subpath(b,current_subpath_edge,false)))return false;current=p;first=p;current_subpath_edge=b->doc->edge_count;open=true;cmd=rel?'l':'L';cubic_reflect=false;quad_reflect=false;continue;}}
251	        if(upper=='M'||upper=='L'||upper=='H'||upper=='V'){cubic_reflect=false;quad_reflect=false;}
252	        if(!svg_shape_point_bounded(p)){svg_shape_fail(b->diag,SVG_SHAPE_ERROR_NUMBER,span.offset+group_start);return false;}
253	        if(!drawn&&!svg_shape_builder_add_edge(b,current,p))return false;
254	        if (segment_index < b->doc->path_segment_count) {
255	            b->doc->path_segments[segment_index].first_edge = segment_first_edge;
256	            b->doc->path_segments[segment_index].edge_count =
257	                b->doc->edge_count - segment_first_edge;
258	        }
259	        current=p; open=true;
260	    }
261	    if(open && (!svg_shape_builder_add_edge(b,current,first) ||
262	                !record_path_subpath(b,current_subpath_edge,false))) return false;
263	    b->doc->shape_subpath_start[b->shape_index] = shape_subpath_start;
264	    b->doc->shape_subpath_count[b->shape_index] =
265	        b->doc->path_subpath_count - shape_subpath_start;
266	    return true;
267	}
