 18	bool svg_shape_point_bounded(geom_point point)
 19	{
 20	    return geom_finite_point(point) && fabs(point.x) <= SHAPE_MAX_COORD &&
 21	           fabs(point.y) <= SHAPE_MAX_COORD;
