271	static double point_segment_distance(geom_point p,geom_point a,geom_point z)
272	{
273	    double dx=z.x-a.x,dy=z.y-a.y,length_squared=dx*dx+dy*dy;
274	    if(length_squared==0.0)return hypot(p.x-a.x,p.y-a.y);
275	    double projection=((p.x-a.x)*dx+(p.y-a.y)*dy)/length_squared;
276	    if(projection<0.0)projection=0.0;
277	    if(projection>1.0)projection=1.0;
278	    geom_point nearest={a.x+projection*dx,a.y+projection*dy};
279	    return hypot(p.x-nearest.x,p.y-nearest.y);
280	}
