  4	pub(crate) fn tolerance(transform: Affine) -> f64 {
  5	    let row_norm = (transform.a.abs() + transform.c.abs()).max(transform.b.abs() + transform.d.abs());
  6	    let column_norm = (transform.a.abs() + transform.b.abs()).max(transform.c.abs() + transform.d.abs());
  7	    let mut scale = (row_norm * column_norm).sqrt();
  8	    if !scale.is_finite() || scale < 1.0 { scale = 1.0; }
  9	    0.25 / scale
 10	}
