 29	fn curve_recursive(edges: &mut Vec<Edge>, transform: Affine, p: [Point; 4], flatness: f64, max_edges: usize, offset: usize, depth: u8) -> Result<(), Diagnostic> {
 30	    if point_segment_distance(p[1], p[0], p[3]).max(point_segment_distance(p[2], p[0], p[3])) <= flatness {
