 34	    let a = midpoint(p[0], p[1]);
 35	    let c = midpoint(p[1], p[2]);
 36	    let d = midpoint(p[2], p[3]);
 37	    let e = midpoint(a, c);
 38	    let f = midpoint(c, d);
 39	    let middle = midpoint(e, f);
 40	    curve_recursive(edges, transform, [p[0], a, e, middle], flatness, max_edges, offset, depth + 1)?;
