 46	fn point_segment_distance(point: Point, from: Point, to: Point) -> f64 {
 47	    let dx = to.x - from.x;
 48	    let dy = to.y - from.y;
 49	    let length_squared = dx * dx + dy * dy;
 50	    if length_squared == 0.0 { return (point.x - from.x).hypot(point.y - from.y); }
 51	    let projection = (((point.x - from.x) * dx + (point.y - from.y) * dy) / length_squared).clamp(0.0, 1.0);
 52	    let nearest = Point { x: from.x + projection * dx, y: from.y + projection * dy };
 53	    (point.x - nearest.x).hypot(point.y - nearest.y)
 54	}
