 37	/// Applies the reference coefficient and translation limits.
 38	pub fn affine_valid(matrix: Affine) -> bool {
 39	    matrix.a.is_finite() && matrix.b.is_finite() && matrix.c.is_finite()
 40	        && matrix.d.is_finite() && matrix.e.is_finite() && matrix.f.is_finite()
 41	        && matrix.a.abs() <= 1.0e12 && matrix.b.abs() <= 1.0e12
 42	        && matrix.c.abs() <= 1.0e12 && matrix.d.abs() <= 1.0e12
 43	        && matrix.e.abs() <= 1.0e6 && matrix.f.abs() <= 1.0e6
 44	}
