 63	pub fn affine_map_point(matrix: Affine, point: Point) -> Option<Point> {
 64	    if !affine_valid(matrix) || !finite_point(point) {
 65	        return None;
 66	    }
 67	    let mapped = Point {
 68	        x: matrix.a * point.x + matrix.c * point.y + matrix.e,
 69	        y: matrix.b * point.x + matrix.d * point.y + matrix.f,
 70	    };
 71	    (finite_point(mapped) && mapped.x.abs() <= 1.0e6 && mapped.y.abs() <= 1.0e6)
 72	        .then_some(mapped)
